return [
  {
    json: {
      demoCase: "healthy",
      minimumItems: 1,
      recordIdField: "recordId",
      sendReceipt: false,
      testReceipt: true,
    },
  },
];

function demoRecords(demoCase) {
  if (demoCase === "empty") return [];
  if (demoCase === "invalid") return [{ unexpectedField: "fictional" }];
  if (demoCase === "duplicates")
    return ["DEMO-001", "DEMO-001", "DEMO-002"].map((recordId) => ({ recordId }));
  if (demoCase === "healthy")
    return ["DEMO-001", "DEMO-002", "DEMO-003"].map((recordId) => ({ recordId }));
  throw new Error("Set demoCase to healthy, empty, invalid, or duplicates.");
}

return demoRecords($("Configure check").first().json.demoCase).map((json) => ({ json }));

function checkOutputs({ records, minimumItems, recordIdField }) {
  const minimum = Number(minimumItems);
  if (!Number.isSafeInteger(minimum) || minimum < 0 || minimum > 1000000000)
    throw new Error("minimumItems must be a non-negative integer, at most 1000000000.");
  const field = String(recordIdField || "").trim();
  if (!field) throw new Error("Set recordIdField to the field identifying a completed output.");
  if (
    !Array.isArray(records) ||
    records.some((record) => !record || typeof record !== "object" || Array.isArray(record))
  )
    throw new Error("records must be an array of objects.");
  const rows = records.filter((record) => Object.keys(record).length > 0);
  const keys = new Set();
  let invalidItems = 0;
  for (const row of rows) {
    const value = row[field];
    const valid =
      (typeof value === "string" && value.trim().length > 0) ||
      (typeof value === "number" && Number.isFinite(value));
    if (!valid) {
      invalidItems++;
      continue;
    }
    keys.add(String(value).trim());
  }
  const items = keys.size;
  const duplicateItems = rows.length - invalidItems - items;
  return {
    checkPassed: items >= minimum && invalidItems === 0,
    checkStatus: invalidItems ? "invalid_output" : items < minimum ? "below_minimum" : "healthy",
    minimumItems: minimum,
    items,
    invalidItems,
    duplicateItems,
  };
}
function receiptReport(result, eventId, testReceipt) {
  const { checkPassed, items, minimumItems, invalidItems, duplicateItems } = result;
  return {
    ...result,
    receipt: {
      eventId,
      success: checkPassed,
      items,
      test: testReceipt === true,
      message:
        "Output check: " +
        items +
        " distinct IDs; minimum " +
        minimumItems +
        "; " +
        invalidItems +
        " invalid; " +
        duplicateItems +
        " duplicates.",
    },
  };
}

const { minimumItems, recordIdField, testReceipt } = $("Configure check").first().json;
const result = checkOutputs({
  records: $input.all().map((item) => item.json),
  minimumItems,
  recordIdField,
});
return [
  {
    json: receiptReport(
      result,
      "n8n:" + $workflow.id + ":" + $execution.id + ":" + $runIndex,
      testReceipt,
    ),
  },
];

function confirmedReceipt(report, reply) {
  if (reply?.received !== true) throw new Error("The receiver did not confirm this receipt.");
  return {
    ...report,
    receiptAccepted: true,
    duplicateReceipt: reply.duplicate === true,
    monitorStatus: reply.status || null,
  };
}

return [{ json: confirmedReceipt($("Check completed outputs").first().json, $input.first().json) }];
